contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(c.owner() == address(this), "test contract must be owner");
        require(address(this).balance >= amount, "insufficient test balance");

        uint balanceBefore = address(c).balance;
        uint depositsCountBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted == (balanceBefore < amount) && (reverted || address(c).balance == balanceBefore - amount) && (reverted || c.depositsCount() == depositsCountBefore));
    }

    receive() external payable {}
}

