pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(c.owner() == address(this));
        vm.assume(address(this).balance >= amount);
        uint balanceBefore = address(c).balance;
        uint256 depositsCountBefore;
        try c.depositsCount() returns (uint256 __r) { depositsCountBefore = __r; } catch { return; }
        bool reverted;
        try c.withdraw(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == (balanceBefore < amount) && (reverted || address(c).balance == balanceBefore - amount) && (reverted || c.depositsCount() == depositsCountBefore));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
